// Des: Prob struct: poll schedule, sense per kind, names
// Flo: stagger poll > sense kind > edge compare > fire
// I/O: Prob + io + now ms > bool fire
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const spawn = @import("spawn"); const netz = std.Io.net;
const evprobbase = @import("ev-prob-base.zig"); const ArmzErro = evprobbase.ArmzErro; const CF = evprobbase.CF; const Cond = evprobbase.Cond; const Kind = evprobbase.Kind; const duraPars = evprobbase.duraPars; const sizePars = evprobbase.sizePars; const evprobplat = @import("ev-prob-plat.zig"); const battOnzz = evprobplat.battOnzz; const freeByte = evprobplat.freeByte; const idleMsec = evprobplat.idleMsec; const procRunn = evprobplat.procRunn; const evprobnetw = @import("ev-prob-netw.zig"); const ipzzLiteChec = evprobnetw.ipzzLiteChec; const statPars = evprobnetw.statPars; const winzConnCond = evprobnetw.winzConnCond;
pub const Prob = struct {
kind: Kind, host: []const u8 = "", port: u16 = 0, urlz: []const u8 = "", path: []const u8 = "", tlsz: bool = false, name: []const u8 = "", thre: u64 = 0, belo: bool = true, batt_onzz: bool = true, last: Cond = .unkn, poll_msec: i64 = CF.poll_midz_msec, poll_next_msec: i64 = 0, unwi: bool = false, unwi_whyz: []const u8 = "", last_erro: bool = false, poll_coun: u32 = 0,
pub fn pollDuez(self: *Prob, nowz_msec: i64) bool { if (self.unwi) return false; if (self.poll_next_msec == 0) { self.poll_next_msec = nowz_msec + self.poll_msec; return false; } if (nowz_msec < self.poll_next_msec) return false; self.poll_next_msec = nowz_msec + self.poll_msec; return true; }
pub fn poll(self: *Prob, iozz: std.Io, nowz_msec: i64) bool { _ = nowz_msec; self.poll_coun += 1; const cond_nowz = self.sens(iozz); const prev = self.last; self.last = cond_nowz; if (cond_nowz != .onzz) return false; if (prev != .offz) return false; return true; }
pub fn adop(self: *Prob, othe: *const Prob) void { self.last = othe.last; self.last_erro = othe.last_erro; self.poll_coun = othe.poll_coun; }
pub fn duez(self: *Prob, iozz: std.Io, nowz_msec: i64) bool { if (!self.pollDuez(nowz_msec)) return false; return self.poll(iozz, nowz_msec); }
fn sens(self: *Prob, iozz: std.Io) Cond { self.last_erro = false; return switch (self.kind) { .tcpz => self.tcpzSens(iozz), .webz => self.webzSens(iozz), .disk => self.diskSens(iozz), .proc, .aliv => self.procSens(iozz), .idle => self.idleSens(iozz), .powe => self.poweSens(iozz), .emai => .unkn }; }
pub fn tcpzSens(self: *Prob, iozz: std.Io) Cond { if (comptime builtin.os.tag == .windows) { if (ipzzLiteChec(self.host)) { if (winzConnCond(self.host, self.port, CF.conn_time_msec)) |cond| { if (cond == .unkn) self.last_erro = true; return cond; } self.last_erro = true; return .unkn; } } const stre = self.dial(iozz) catch |erro| return connErroCond(self, erro); stre.close(iozz); return .onzz; }
fn dial(self: *Prob, iozz: std.Io) !netz.Stream { const opts: netz.IpAddress.ConnectOptions = .{ .mode = .stream }; if (netz.IpAddress.parse(self.host, self.port)) |ipzz| { return ipzz.connect(iozz, opts); } else |_| {} const hnam = try netz.HostName.init(self.host); return hnam.connect(iozz, self.port, opts); }
pub fn webzSens(self: *Prob, iozz: std.Io) Cond { if (comptime builtin.os.tag == .windows) { if (ipzzLiteChec(self.host)) { const conn = winzConnCond(self.host, self.port, CF.conn_time_msec); if (conn) |cond| { if (cond == .offz) return .offz; } else { self.last_erro = true; return .unkn; } } } const stre = self.dial(iozz) catch |erro| return connErroCond(self, erro); defer stre.close(iozz); var bufz_reqz: [1024]u8 = undefined; const reqz = std.fmt.bufPrint(&bufz_reqz, "GET {s} HTTP/1.1\r\nHost: {s}\r\nUser-Agent: auto-task-probe\r\nAccept: */*\r\nConnection: close\r\n\r\n", .{ self.path, self.host }) catch { self.last_erro = true; return .unkn; }; var bufz_writ: [256]u8 = undefined; var wrtr = stre.writer(iozz, &bufz_writ); wrtr.interface.writeAll(reqz) catch { self.last_erro = true; return .unkn; }; wrtr.interface.flush() catch { self.last_erro = true; return .unkn; }; var bufz_read: [CF.http_head_maxz]u8 = undefined; var rdrz = stre.reader(iozz, &bufz_read); const leng = rdrz.interface.readSliceShort(&bufz_read) catch { self.last_erro = true; return .unkn; }; if (leng == 0) { self.last_erro = true; return .unkn; } const code = statPars(bufz_read[0..leng]) orelse { self.last_erro = true; return .unkn; }; return if (code >= 500) .offz else .onzz; }
pub fn diskSens(self: *Prob, iozz: std.Io) Cond { const free = freeByte(iozz, self.path) orelse { self.last_erro = true; return .unkn; }; const hitz = if (self.belo) free < self.thre else free > self.thre; return if (hitz) .onzz else .offz; }
fn procSens(self: *Prob, iozz: std.Io) Cond { const runn = procRunn(iozz, self.name) orelse { self.last_erro = true; return .unkn; }; const hitz = if (self.kind == .proc) runn else !runn; return if (hitz) .onzz else .offz; }
pub fn idleSens(self: *Prob, iozz: std.Io) Cond { const idle_msec = idleMsec(iozz) orelse { self.last_erro = true; return .unkn; }; return if (idle_msec >= self.thre) .onzz else .offz; }
fn poweSens(self: *Prob, iozz: std.Io) Cond { const batt_nowz = battOnzz(iozz) orelse { self.last_erro = true; return .unkn; }; const hitz = if (self.batt_onzz) batt_nowz else !batt_nowz; return if (hitz) .onzz else .offz; }
pub fn typeName(self: *const Prob) []const u8 { return switch (self.kind) { .aliv => "live", .disk => "disk", .emai => "mail", .idle => "idle", .powe => "powe", .proc => "proc", .tcpz => "tcpr", .webz => "webs" }; }
pub fn statName(self: *const Prob) []const u8 { if (self.unwi) return "unwired"; if (self.poll_coun == 0) return "priming"; if (self.last_erro) return "unreadable"; return switch (self.last) { .unkn => "unreadable", .offz => "waiting", .onzz => "satisfied" }; }
};
fn connErroCond(prob: *Prob, erro: anyerror) Cond { return switch (erro) { error.ConnectionRefused, error.ConnectionResetByPeer, error.HostUnreachable, error.NetworkUnreachable, error.NetworkDown, error.Timeout, error.TimedOut, error.UnknownHostName, error.AddressUnavailable => .offz, else => { prob.last_erro = true; return .unkn; } }; }
